`timescale 1ns / 1ps
`default_nettype none

// ============================================================
// Module      : tb_bit_flip_channel
// Description : Self-checking testbench for bit_flip_channel.v
// Reference   : Uses data/encoded.hex, data/config.hex, data/corrupted.hex
//               generated by python/export_hex.py
// ============================================================

module tb_bit_flip_channel;
    localparam integer CLK_PERIOD_NS = 20;
    localparam integer TRANSACTIONS  = 384;

    reg        i_clk      = 1'b0;
    reg        i_rst_n    = 1'b0;
    reg  [7:0] i_codeword = 8'h00;
    reg        i_valid    = 1'b0;
    reg  [1:0] i_err_mode = 2'b00;

    wire [7:0] o_codeword;
    wire       o_valid;

    reg [7:0] encoded_ref   [0:TRANSACTIONS-1];
    reg [7:0] config_ref    [0:TRANSACTIONS-1];
    reg [7:0] corrupted_ref [0:TRANSACTIONS-1];

    integer test_count  = 0;
    integer error_count = 0;
    integer i;

    always #(CLK_PERIOD_NS/2) i_clk = ~i_clk;

    bit_flip_channel dut (
        .i_clk      (i_clk),
        .i_rst_n    (i_rst_n),
        .i_codeword (i_codeword),
        .i_valid    (i_valid),
        .i_err_mode (i_err_mode),
        .o_codeword (o_codeword),
        .o_valid    (o_valid)
    );

    task automatic check_output(
        input bit       expected_valid,
        input [7:0]     expected_word,
        input bit       check_word,
        input string    description
    );
    begin
        test_count = test_count + 1;
        if (o_valid !== expected_valid ||
            (check_word && o_codeword !== expected_word)) begin
            error_count = error_count + 1;
            $display("FAIL [%0t] %s: valid=%b (exp %b), codeword=%02h (exp %02h)",
                     $time, description, o_valid, expected_valid,
                     o_codeword, expected_word);
        end
    end
    endtask

    initial begin
        // Load verification vectors exported by Python golden model
        $readmemh("data/encoded.hex", encoded_ref);
        $readmemh("data/config.hex", config_ref);
        $readmemh("data/corrupted.hex", corrupted_ref);

        // Verify initial reset state
        repeat (3) @(posedge i_clk);
        #1;
        check_output(1'b0, 8'h00, 1'b1, "reset values");

        @(negedge i_clk);
        i_rst_n = 1'b1;

        // Run all 384 golden transactions sequentially
        for (i = 0; i < TRANSACTIONS; i = i + 1) begin
            // Drive input codeword ahead of rising edge
            @(negedge i_clk);
            i_codeword = encoded_ref[i];
            i_err_mode = config_ref[i][1:0];
            i_valid    = 1'b1;

            // Clock Edge: input sampled -> output becomes valid (1-clock latency)
            @(posedge i_clk); #1;
            check_output(1'b1, corrupted_ref[i], 1'b1, "valid output");

            // Deassert valid
            @(negedge i_clk);
            i_valid    = 1'b0;
            i_codeword = 8'h00;

            // Next Clock Edge: valid clears, output holds/clears
            @(posedge i_clk); #1;
            check_output(1'b0, 8'h00, 1'b0, "valid clears");
        end

        // Synchronous reset test
        @(negedge i_clk);
        i_codeword = 8'hAA;
        i_valid    = 1'b1;
        @(posedge i_clk); #1;
        @(negedge i_clk);
        i_valid = 1'b0;
        i_rst_n = 1'b0;
        @(posedge i_clk); #1;
        check_output(1'b0, 8'h00, 1'b1, "held reset");
        @(negedge i_clk);
        i_rst_n = 1'b1;
        @(posedge i_clk); #1;
        check_output(1'b0, 8'h00, 1'b1, "released reset");

        $display("Bit flip channel checks: %0d, errors: %0d", test_count, error_count);
        if (error_count == 0)
            $display("PASS: tb_bit_flip_channel (All %0d transactions matched!)", TRANSACTIONS);
        else
            $fatal(1, "FAIL: tb_bit_flip_channel (%0d errors)", error_count);

        $finish;
    end

endmodule

`default_nettype wire
